    "g.heroTitle": "A to Z Guide: Flow Media Downloader",
    "g.heroLead": "The complete manual for downloading generated videos and images from Google Flow (flow.google.com) with sequential numbering, 4K/1080p upscale interception, and missing files recovery.",
    "g.tocTitle": "Table of Contents (A to Z)",
