    "guide.title": "Flow Downloader Nasıl Kullanılır",
    "guide.desc": "Yüksek çözünürlüklü video ve görselleri indirmek için simgeli adım adım talimatlar.",
    "guide.badge1": "ADIM 1",
    "guide.badge2": "ADIM 2",
    "guide.badge3": "ADIM 3",
    "guide.badge4": "ADIM 4",
    "guide.badge5": "ADIM 5",
    "guide.badge6": "ADIM 6",
    "guide.badge7": "ADIM 7",
    "guide.step1Title": "Google Flow'u Açın",
    "guide.step1Text": "Chrome'da <a href=\"https://flow.google.com\" target=\"_blank\" rel=\"noopener\">flow.google.com</a> adresini açın ve oluşturulan videoları içeren projenize girin.",
    "guide.step2Title": "Proje Tuvalini Tarayın",
    "guide.step2Text": "<strong>\"Projeyi Tara\"</strong> düğmesine tıklayın. Uzantı tuvali tarar ve oluşturulan tüm videoları ve görselleri listeler.",
    "guide.step3Title": "Listeyi Düzenleyin & Klipleri Silin",
    "guide.step3Text": "Tespit edilen medyayı inceleyin. İstemediğiniz klibin yanındaki <strong>🗑️ sil düğmesine</strong> tıklayın veya listeyi sıfırlamak için <strong>\"Tümünü Temizle\"</strong>ye basın.",
    "guide.step4Title": "4K / HD Kalitesini Seçin",
    "guide.step4Text": "Flow'un yapay zeka yükseltmesini tetiklemek için <strong>4K Ultra HD</strong> veya <strong>1080p HD</strong> seçin ya da hızlı indirme için <strong>Orijinal (720p)</strong> seçin.",
    "guide.step5Title": "Sıralı Numaralandırma",
    "guide.step5Text": "Dosyaların hikaye akışınıza uyması için <strong>\"Önce en eski\"</strong> seçin (<code>001.mp4</code>, <code>002.mp4</code>). Ön ek ve klasör adı belirleyin.",
    "guide.step6Title": "Tümünü İndirin",
    "guide.step6Text": "<strong>\"Tümünü İndir\"</strong>e tıklayın. Uzantı sıralamayı otomatik işler, yükseltmeleri takip eder ve tüm dosyaları kaydeder.",
    "guide.step7Title": "Eksik Dosyaları Kaydet (Kurtarma)",
    "guide.step7Text": "İnternet koptu veya yeni klipler mi oluşturdunuz? <strong>\"Eksik Dosyaları Kaydet\"</strong>e tıklayın! Yalnızca bilgisayarınızda eksik olanları indirir.",
    "guide.btnFullGuide": "📖 A'dan Z'ye Tam Kılavuzu Aç (Yeni Sekme)",
    "faq.title": "Sık Sorulan Sorular (SSS)",
    "faq.desc": "Flow Media Downloader hakkında en çok merak edilen sorular ve uzman cevapları.",
    "faq.q1": "4K Ultra HD ve 1080p Yükseltme arka planda nasıl çalışır?",
    "faq.a1": "Google Flow varsayılan olarak tuvalde 720p önizleme sunar. <strong>4K Ultra HD</strong> veya <strong>1080p HD</strong> seçtiğinizde uzantı Flow'un üç nokta menüsünü tetikler, buluttan yükseltmeyi ister ve yüksek çözünürlüklü dosyayı sıralı olarak bilgisayarınıza kaydeder.",
    "faq.q2": "\"Eksik Dosyaları Kaydet\" ne işe yarar?",
    "faq.a2": "İndirme sırasında internetiniz kesilirse veya projeye sonradan yeni klipler eklerseniz <strong>\"Eksik Dosyaları Kaydet\"</strong> düğmesine basın. Uzantı yalnızca bilgisayarınızda olmayan dosyaları tespit edip indirir, kopyaları engeller.",
    "faq.q3": "Sıralı numaralandırma nasıl işler (001.mp4, 002.mp4)?",
    "faq.a3": "<strong>\"Önce en eski\"</strong> seçildiğinde projenizde ilk üretilen videoya <code>001</code>, ikinciye <code>002</code> verilir. Başlangıç numarasını, basamak sayısını ve özel ön ekleri dilediğiniz gibi ayarlayabilirsiniz.",
    "faq.q4": "Hem videoları hem de görselleri indirebilir miyim?",
    "faq.a4": "Evet! Kayıt Türleri menüsünden <strong>\"Videolar ve Görseller\"</strong>, <strong>\"Yalnızca Videolar\"</strong> veya <strong>\"Yalnızca Görseller\"</strong> seçebilirsiniz.",
    "faq.q5": "Google Flow sekmesini açık tutmam gerekir mi?",
    "faq.a5": "Evet. Chrome'un arka plan zamanlayıcılarını yavaşlatmaması için Flow sekmesini açık tutun. Bilgisayarınızın uyku moduna geçmesini engelleyen güç kilidi uzantıya dahildir.",
    "faq.q6": "Flow Media Downloader ücretsiz mi?",
    "faq.a6": "Evet, tamamen ücretsizdir. Abonelik ücreti, jeton veya indirme limiti yoktur. Muhammad Asad tarafından topluluk için geliştirilmiştir.",
    "faq.q7": "Medya verilerim gizli ve güvende mi?",
    "faq.a7": "Kesinlikle %100 gizlidir. Tüm dosyalar Google Flow'dan doğrudan kendi bilgisayarınıza indirilir. Hiçbir medyanız üçüncü taraflara gönderilmez veya analiz edilmez.",
    "faq.q8": "Destek için geliştirici Muhammad Asad ile nasıl iletişim kurabilirim?",
    "faq.a8": "WhatsApp üzerinden doğrudan yazabilirsiniz: <strong>+92 311 6730583</strong> veya e-posta: <strong>autoflow.asad@gmail.com</strong>. Hızlı yanıt verilir!",
    "footer.guide": "📖 Kılavuz",
    "footer.faq": "❓ SSS",
