    "sup.freeBannerDesc": "Abonelik yok, deneme süresi yok, sınır yok. Dilediğiniz kadar video ve görsel indirin.",
    "sup.lead": "Sorularınız veya yardım talebiniz mi var? Doğrudan geliştiriciyle sohbet edin.",
