    "guide.title": "Flow Downloader का उपयोग कैसे करें",
    "guide.desc": "उच्च-रिज़ॉल्यूशन वीडियो और चित्र प्राप्त करने के लिए चरण-दर-चरण निर्देश।",
    "guide.badge1": "चरण 1",
    "guide.badge2": "चरण 2",
    "guide.badge3": "चरण 3",
    "guide.badge4": "चरण 4",
    "guide.badge5": "चरण 5",
    "guide.badge6": "चरण 6",
    "guide.badge7": "चरण 7",
    "guide.step1Title": "गूगल फ्लो खोलें",
    "guide.step1Text": "Chrome में <a href=\"https://flow.google.com\" target=\"_blank\" rel=\"noopener\">flow.google.com</a> खोलें और अपना प्रोजेक्ट लोड करें।",
    "guide.step2Title": "प्रोजेक्ट कैनवास स्कैन करें",
    "guide.step2Text": "<strong>\"प्रोजेक्ट स्कैन करें\"</strong> पर क्लिक करें। एक्सटेंशन कैनवास को स्कैन करके सभी वीडियो और छवियों को सूचीबद्ध करेगा।",
    "guide.step3Title": "सूची संपादित करें और क्लिप हटाएं",
    "guide.step3Text": "सूची देखें। किसी अवांछित क्लिप के आगे <strong>🗑️ डिलीट बटन</strong> दबाएं या <strong>\"सब साफ़ करें\"</strong> पर क्लिक करें।",
    "guide.step4Title": "4K / HD क्वालिटी चुनें",
    "guide.step4Text": "<strong>4K Ultra HD</strong> या <strong>1080p HD</strong> चुनें या तेज़ डाउनलोड के लिए <strong>ओरिजिनल (720p)</strong> चुनें।",
    "guide.step5Title": "क्रमिक नंबरिंग",
    "guide.step5Text": "फ़ाइलों को क्रम में रखने के लिए <strong>\"पहले सबसे पुराना\"</strong> चुनें (<code>001.mp4</code>, <code>002.mp4</code>)।",
    "guide.step6Title": "सभी डाउनलोड करें",
    "guide.step6Text": "<strong>\"सभी डाउनलोड करें\"</strong> पर क्लिक करें। एक्सटेंशन स्वचालित रूप से प्रत्येक फ़ाइल को सहेज लेगा।",
    "guide.step7Title": "मिसिंग फ़ाइलें सहेजें (रिकवरी)",
    "guide.step7Text": "इंटरनेट बंद हुआ या नए क्लिप बने? <strong>\"मिसिंग फ़ाइलें सहेजें\"</strong> दबाएं! केवल छूटी हुई फ़ाइलें ही डाउनलोड होंगी।",
    "guide.btnFullGuide": "📖 पूरी A to Z गाइड खोलें (नया टैब)",
    "faq.title": "सामान्य प्रश्न और उत्तर (FAQ)",
    "faq.desc": "Flow Media Downloader के बारे में अक्सर पूछे जाने वाले सवाल।",
    "faq.q1": "4K Ultra HD और 1080p अपस्केल कैसे काम करता है?",
    "faq.a1": "गूगल फ्लो कैनवास पर 720p प्रीव्यू दिखाता है। जब आप 4K या 1080p चुनते हैं, तो एक्सटेंशन क्लाउड से अपस्केल फ़ाइल प्राप्त करके क्रम से आपके डिस्क पर डाउनलोड करता है।",
    "faq.q2": "\"मिसिंग फ़ाइलें सहेजें\" क्या करता है?",
    "faq.a2": "यदि डाउनलोड रुक जाए या आप बाद में नए क्लिप बनाएं, तो यह बटन केवल छूटी हुई फ़ाइलें डाउनलोड करता है, कोई डुप्लिकेट नहीं बनता।",
    "faq.q3": "क्रमिक नंबरिंग कैसे काम करती है (001.mp4, 002.mp4)?",
    "faq.a3": "\"पहले सबसे पुराना\" चुनने से सबसे पहले बनी वीडियो 001 और दूसरी 002 बन जाती है, जिससे एडिटिंग टाइमलाइन पर रखना आसान होता है।",
    "faq.q4": "क्या मैं वीडियो और चित्र दोनों डाउनलोड कर सकता हूँ?",
    "faq.a4": "हाँ! डाउनलोड सेटिंग्स में \"वीडियो और चित्र दोनों\" चुनें।",
    "faq.q5": "क्या गूगल फ्लो का टैब खुला रखना आवश्यक है?",
    "faq.a5": "हाँ, Chrome में Flow टैब खुला रखें। कंप्यूटर को स्लीप मोड में जाने से रोकने के लिए इसमें पावर लॉक शामिल है।",
    "faq.q6": "क्या Flow Media Downloader मुफ़्त है?",
    "faq.a6": "हाँ, हमेशा के लिए बिल्कुल मुफ़्त। कोई छिपी हुई फीस, टोकन या दैनिक सीमा नहीं। Muhammad Asad द्वारा निर्मित।",
    "faq.q7": "क्या मेरा मीडिया डेटा सुरक्षित और निजी है?",
    "faq.a7": "पूरी तरह से निजी। सभी फाइलें सीधे आपके कंप्यूटर पर डाउनलोड होती हैं, किसी सर्वर पर नहीं भेजी जातीं।",
    "faq.q8": "डेवलपर से सहायता के लिए कैसे संपर्क करें?",
    "faq.a8": "सीधे व्हाट्सएप <strong>+92 311 6730583</strong> या ईमेल <strong>autoflow.asad@gmail.com</strong> पर चैट कर सकते हैं।",
    "footer.guide": "📖 गाइड",
    "footer.faq": "❓ सवाल",
    "footer.wa": "💬 व्हाट्सएप सपोर्ट",
    "footer.privacy": "🛡️ प्राइवेसी",
    "footer.copy": "Flow Media Downloader — मीडिया डाउनलोडर · Muhammad Asad",
    "sup.title": "मदद और सपोर्ट",
    "sup.freeBannerTitle": "मुफ़्त और असीमित टूल",
    "sup.freeBannerDesc": "कोई सब्सक्रिप्शन नहीं, कोई सीमा नहीं। जितनी चाहें वीडियो और तस्वीरें डाउनलोड करें।",
    "sup.lead": "कोई सवाल या मदद चाहिए? सीधे डेवलपर से संपर्क करें।",
    "sup.waBtn": "व्हाट्सएप पर चैट करें: +92 311 6730583",
