    "guide.step1Title": "گوگل فلو کھولیں",
    "guide.step1Text": "کروم میں <a href=\"https://flow.google.com\" target=\"_blank\" rel=\"noopener\">flow.google.com</a> کھولیں اور وہ پروجیکٹ کھولیں جس میں ویڈیوز موجود ہوں۔",
    "guide.step2Title": "کینوس اسکین کریں",
    "guide.step2Text": "<strong>\"پروجیکٹ اسکین کریں\"</strong> پر کلک کریں۔ ایکسٹینشن کینوس کو اسکین کر کے تمام ویڈیوز اور تصاویر کو لسٹ میں لے آئے گی۔",
    "guide.step3Title": "فہرست چیک کریں اور ڈیلیٹ کریں",
    "guide.step3Text": "فہرست دیکھیں۔ جس ویڈیو کو نہیں چاہیے اس کے آگے <strong>🗑️ ڈیلیٹ بٹن</strong> دبائیں یا <strong>\"سب صاف کریں\"</strong> پر کلک کریں۔",
    "guide.step4Title": "4K / HD کوالٹی منتخب کریں",
    "guide.step4Text": "<strong>4K Ultra HD</strong> یا <strong>1080p HD</strong> منتخب کریں تاکہ فلو کا AI انجن ہائی ریزولوشن تیار کرے۔",
    "guide.step5Title": "ترتیب وار نمبرنگ",
    "guide.step5Text": "<strong>\"پہلے سب سے پرانی\"</strong> چنیں تاکہ فائلز ترتیب سے محفوظ ہوں (<code>001.mp4</code>, <code>002.mp4</code>)۔",
    "guide.step6Title": "سب ڈاؤن لوڈ کریں",
    "guide.step6Text": "<strong>\"سب ڈاؤن لوڈ کریں\"</strong> پر کلک کریں۔ ایکسٹینشن خودکار طریقے سے فائلوں کو ترتیب کے ساتھ محفوظ کرے گی۔",
    "guide.step7Title": "گمشدہ فائلیں محفوظ کریں",
    "guide.step7Text": "انٹرنیٹ بند ہوا یا نئی ویڈیو بنی؟ <strong>\"گمشدہ فائلیں محفوظ کریں\"</strong> دبائیں، صرف وہی فائلیں ڈاؤن لوڈ ہوں گی جو آپ کے پاس نہیں ہیں۔",
    "guide.btnFullGuide": "📖 مکمل A to Z رہنما کھولیں (نیا ٹیب)",
    "faq.title": "عام سوالات اور جوابات (FAQ)",
    "faq.desc": "فلو میڈیا ڈاؤن لوڈر کے بارے میں اکثر پوچھے جانے والے سوالات۔",
    "faq.q1": "4K Ultra HD اور 1080p اپ اسکیل کیسے کام کرتا ہے؟",
    "faq.a1": "گوگل فلو عام طور پر 720p ویڈیو دکھاتا ہے۔ جب آپ 4K یا 1080p چنتے ہیں تو ایکسٹینشن فلو کے کلاؤڈ سے ہائی ریزولوشن تیار کروا کر آپ کے کمپیوٹر پر ڈاؤن لوڈ کرتی ہے۔",
    "faq.q2": "\"گمشدہ فائلیں محفوظ کریں\" کیا کرتا ہے؟",
    "faq.a2": "اگر انٹرنیٹ منقطع ہو جائے یا بعد میں نئی ویڈیوز بنائیں تو یہ بٹن صرف وہی فائلیں ڈاؤن لوڈ کرتا ہے جو آپ کے پاس موجود نہیں ہیں۔ ڈپلیکیٹ نہیں بنتی۔",
    "faq.q3": "ترتیب وار نمبرنگ کیسے کام کرتی ہے (001.mp4, 002.mp4)؟",
    "faq.a3": "\"پہلے سب سے پرانی\" سے پروجیکٹ کی پہلی ویڈیو 001 بنتی ہے اور دوسری 002۔ اس سے ایڈیٹنگ سافٹ ویئر میں ٹائم لائن پر رکھنا بے حد آسان ہو جاتا ہے۔",
    "faq.q4": "کیا میں ویڈیوز اور تصاویر دونوں ڈاؤن لوڈ کر سکتا ہوں؟",
    "faq.a4": "جی ہاں! ڈاؤن لوڈ سیٹنگز میں \"ویڈیوز اور تصاویر دونوں\" منتخب کریں۔",
    "faq.q5": "کیا گوگل فلو کا ٹیب کھلا رکھنا ضروری ہے؟",
    "faq.a5": "جی ہاں، کروم میں فلو کا ٹیب کھلا رہنے دیں۔ کمپیوٹر کو نیند میں جانے سے روکنے کے لیے ایکسٹینشن میں پاور لاک موجود ہے۔",
    "faq.q6": "کیا Flow Media Downloader مفت ہے؟",
    "faq.a6": "جی ہاں، ہمیشہ کے لیے بالکل مفت۔ کوئی فیس، کوئی ٹوکن اور کوئی حد نہیں۔ Muhammad Asad کی طرف سے کمیونٹی کے لیے تحفہ۔",
    "faq.q7": "کیا میرا میڈیا ڈیٹا محفوظ اور نجی ہے؟",
    "faq.a7": "بالکل 100 فیصد محفوظ۔ تمام فائلیں براہ راست آپ کے کمپیوٹر پر محفوظ ہوتی ہیں اور کسی سرور پر اپلوڈ نہیں کی جاتیں۔",
    "faq.q8": "ڈیولپر سے کیسے رابطہ کیا جائے؟",
    "faq.a8": "آپ براہِ راست واٹس ایپ <strong>+92 311 6730583</strong> یا ای میل <strong>autoflow.asad@gmail.com</strong> پر رابطہ کر سکتے ہیں۔",
