    "guide.step1Title": "গুগল ফ্লো খুলুন",
    "guide.step1Text": "ক্রোম ব্রাউজারে <a href=\"https://flow.google.com\" target=\"_blank\" rel=\"noopener\">flow.google.com</a> খুলুন এবং আপনার প্রজেক্টে যান।",
    "guide.step2Title": "প্রজেক্ট ক্যানভাস স্ক্যান করুন",
    "guide.step2Text": "<strong>\"প্রজেক্ট স্ক্যান করুন\"</strong> বাটনে ক্লিক করুন। এক্সটেনশন ক্যানভাস স্ক্যান করে সমস্ত ভিডিও এবং ছবি তালিকাভুক্ত করবে।",
    "guide.step3Title": "তালিকা সাজান ও ক্লিপ মুছুন",
    "guide.step3Text": "তালিকাটি দেখুন। অপ্রয়োজনীয় ক্লিপের পাশে <strong>🗑️ ডিলিট আইকনে</strong> ক্লিক করুন বা পুরো তালিকা মুছতে <strong>\"সব মুছুন\"</strong> চাপুন।",
    "guide.step4Title": "4K / HD কোয়ালিটি নির্বাচন করুন",
    "guide.step4Text": "উচ্চ রেজোলিউশন পেতে <strong>4K Ultra HD</strong> বা <strong>1080p HD</strong> নির্বাচন করুন, অথবা দ্রুত ডাউনলোডের জন্য <strong>অরিজিনাল (720p)</strong> নির্বাচন করুন।",
    "guide.step5Title": "ধারাবাহিক নাম্বারিং",
    "guide.step5Text": "ফাইলের ক্রম ঠিক রাখতে <strong>\"প্রথমে প্রাচীনতম\"</strong> নির্বাচন করুন (<code>001.mp4</code>, <code>002.mp4</code>)।",
    "guide.step6Title": "সব ডাউনলোড করুন",
    "guide.step6Text": "<strong>\"সব ডাউনলোড করুন\"</strong> বাটনে ক্লিক করুন। এক্সটেনশন স্বয়ংক্রিয়ভাবে প্রতিটি ফাইল সংরক্ষণ করবে।",
    "guide.step7Title": "মিসিং ফাইল সেভ করুন (রিকভারি)",
    "guide.step7Text": "ইন্টারনেট বিচ্ছিন্ন হয়েছে বা নতুন ক্লিপ তৈরি করেছেন? <strong>\"মিসিং ফাইল সেভ করুন\"</strong> চাপুন! শুধুমাত্র অনুপস্থিত ফাইলগুলো ডাউনলোড হবে।",
    "guide.btnFullGuide": "📖 সম্পূর্ণ A to Z গাইড খুলুন (নতুন ট্যাব)",
    "faq.title": "সাধারণ প্রশ্নোত্তর (FAQ)",
    "faq.desc": "Flow Media Downloader সম্পর্কে প্রায়শই জিজ্ঞাসিত প্রশ্ন ও উত্তর।",
    "faq.q1": "4K Ultra HD ও 1080p আপস্কেল কীভাবে কাজ করে?",
    "faq.a1": "গুগল ফ্লো ক্যানভাসে সাধারণত 720p রেজোলিউশন দেখায়। আপনি যখন 4K বা 1080p চান, এক্সটেনশন ক্লাউড থেকে আপস্কেল ফাইলটি গ্রহণ করে ক্রমানুসারে আপনার কম্পিউটারে ডাউনলোড করে।",
    "faq.q2": "\"মিসিং ফাইল সেভ করুন\" কী করে?",
    "faq.a2": "ডাউনলোডের সময় নেটওয়ার্ক সমস্যা হলে বা নতুন ভিডিও তৈরি করলে এটি চাপুন। এটি শুধুমাত্র অনুপস্থিত ফাইলগুলো খুঁজে ডাউনলোড করে, কোনো ডুপ্লিকেট হয় না।",
    "faq.q3": "ধারাবাহিক নাম্বারিং কীভাবে কাজ করে (001.mp4, 002.mp4)?",
    "faq.a3": "\"প্রথমে প্রাচীনতম\" বেছে নিলে প্রথম তৈরি ভিডিওটি 001 এবং দ্বিতীয়টি 002 হিসেবে সংরক্ষিত হয়। এটি ভিডিও এডিটিংকে অনেক সহজ করে তোলে।",
    "faq.q4": "আমি কি ভিডিও এবং ছবি উভয়ই ডাউনলোড করতে পারি?",
    "faq.a4": "হ্যাঁ! ডাউনলোড সেটিংসের ড্রপডাউন থেকে \"ভিডিও এবং ছবি উভয়ই\" নির্বাচন করুন।",
    "faq.q5": "গুগল ফ্লো ট্যাব কি খোলা রাখা প্রয়োজন?",
    "faq.a5": "হ্যাঁ, ক্রোম যাতে ব্যাকগ্রাউন্ডের কাজ ধীর না করে দেয় তাই ফ্লো ট্যাবটি খোলা রাখুন। কম্পিউটার স্লিপ মোডে যাওয়া রোধ করতে এতে স্বয়ংক্রিয় পাওয়ার লক রয়েছে।",
    "faq.q6": "Flow Media Downloader কি বিনামূল্যে ব্যবহার করা যায়?",
    "faq.a6": "হ্যাঁ, সম্পূর্ণ বিনামূল্যে। কোনো সাবস্ক্রিপশন ফি, টোকেন খরচ বা ডাউনলোডের সীমা নেই। Muhammad Asad দ্বারা তৈরি।",
    "faq.q7": "আমার মিডিয়া ডেটা কি ব্যক্তিগত এবং নিরাপদ?",
    "faq.a7": "সম্পূর্ণ ১০০% ব্যক্তিগত। সমস্ত মিডিয়া সরাসরি গুগল ফ্লো থেকে আপনার কম্পিউটারে ডাউনলোড হয়, কোনো সার্ভারে আপলোড হয় না।",
    "faq.q8": "সাপোর্টের জন্য কীভাবে যোগাযোগ করব?",
    "faq.a8": "সরাসরি হোয়াটসঅ্যাপ <strong>+92 311 6730583</strong> অথবা ইমেইল <strong>autoflow.asad@gmail.com</strong>-এ যোগাযোগ করতে পারেন।",
    "footer.guide": "📖 গাইড",
    "footer.faq": "❓ প্রশ্নোত্তর",
    "footer.wa": "💬 হোয়াটসঅ্যাপ সাপোর্ট",
