    "sup.freeBannerDesc": "কোনো সাবস্ক্রিপশন নেই, ট্রায়াল নেই, সীমা নেই। যত খুশি ভিডিও এবং ছবি ডাউনলোড করুন।",
    "sup.lead": "কোনো প্রশ্ন বা সমস্যা থাকলে সরাসরি ডেভেলপারের সাথে চ্যাট করুন।",
