    "afm.title": "AutoFlow: Veo AI Prompt Suite",
    "afm.subtag": "Batch Generation & Workflow Powerhouse for Google Flow",
    "afm.bannerDesc": "While Flow Downloader extracts and saves your media, AutoFlow creates, matrices, and submits prompts on Google Flow!",
    "afm.b1Title": "Bulk Queue Automation",
    "afm.b1Desc": "Queue prompts in bulk with one click. AutoFlow feeds them automatically into Google Flow without manual typing or repetitive clicks.",
    "afm.b2Title": "Prompt Matrix & Variations",
    "afm.b2Desc": "Combine camera angles, lighting, cinematic styles, and character actions into hundreds of scene variations instantly.",
    "afm.b3Title": "Auto Reference Image Binding",
