    "afm.b4Title": "Save 5+ Hours of Daily Work",
    "afm.b4Desc": "Hands-free background generation. Smart pacing and interval delays prevent Google Flow rate limits while you sleep or work.",
    "afm.b5Title": "The Ultimate Complete Duo",
    "afm.b5Desc": "AutoFlow generates your videos on Flow canvas → Flow Downloader downloads them in sequential 4K order. A complete automated AI studio!",
