    "g.heroBadge2": "সরাসরি হোয়াটসঅ্যাপ সহায়তা",
    "g.heroTitle": "A to Z গাইড: ফ্লো মিডিয়া ডাউনলোডার",
    "g.heroLead": "Google Flow (flow.google.com) থেকে জেনারেট করা ভিডিও এবং ছবি ক্রমানুসারে এবং 4K আপস্কেলে ডাউনলোড করার সম্পূর্ণ ম্যানুয়াল।",
    "g.tocTitle": "সূচিপত্র (A to Z)",
    "g.tocA": "ওভারভিউ এবং আর্কিটেকচার",
    "g.tocB": "ক্রোমে সেটআপ এবং পিন করা",
