    "guide.title": "Cómo Usar Flow Downloader",
    "guide.desc": "Instrucciones sencillas paso a paso para descargar videos e imágenes en alta resolución.",
    "guide.badge1": "PASO 1",
    "guide.badge2": "PASO 2",
    "guide.badge3": "PASO 3",
