    "guide.badge6": "PASO 6",
    "guide.badge7": "PASO 7",
    "guide.step1Title": "Abrir Google Flow",
    "guide.step1Text": "Abra <a href=\"https://flow.google.com\" target=\"_blank\" rel=\"noopener\">flow.google.com</a> en Chrome y cargue su proyecto.",
    "guide.step2Title": "Escanear Lienzo del Proyecto",
    "guide.step2Text": "Haga clic en <strong>\"Escanear Proyecto\"</strong>. La extensión rastrea su lienzo y registra todos los videos e imágenes.",
    "guide.step3Title": "Organizar Lista y Eliminar Clips",
    "guide.step3Text": "Revise los medios detectados. Haga clic en el botón <strong>🗑️ eliminar</strong> para descartar clips innecesarios o en <strong>\"Limpiar Todo\"</strong>.",
    "guide.step4Title": "Elegir Calidad 4K / HD",
    "guide.step4Text": "Seleccione <strong>4K Ultra HD</strong> o <strong>1080p HD</strong> para activar el escalado por IA de Flow, u <strong>Original (720p)</strong> para descarga directa.",
    "guide.step5Title": "Numeración Secuencial",
    "guide.step5Text": "Elija <strong>\"Más antiguos primero\"</strong> para mantener el orden cronológico (<code>001.mp4</code>, <code>002.mp4</code>).",
    "guide.step6Title": "Descargar Todo",
    "guide.step6Text": "Haga clic en <strong>\"Descargar Todo\"</strong>. La extensión procesa la cola y guarda cada archivo automáticamente.",
    "guide.step7Title": "Guardar Archivos Faltantes (Recuperación)",
    "guide.step7Text": "¿Se cortó la conexión o generó nuevos clips? ¡Haga clic en <strong>\"Guardar Archivos Faltantes\"</strong>! Solo se descargarán los clips que faltan.",
    "guide.btnFullGuide": "📖 Abrir Guía Completa de la A a la Z (Nueva Pestaña)",
    "faq.title": "Common Questions (FAQ)",
    "faq.desc": "Frequently asked questions and expert answers about Flow Media Downloader.",
    "faq.q1": "How does 4K Ultra HD & 1080p Upscale work?",
    "faq.a1": "Google Flow renders 720p preview videos on the canvas by default. When you choose <strong>4K Ultra HD</strong> or <strong>1080p HD</strong>, Flow Downloader triggers Flow's internal 3-dots resolution menu, requests the high-res render from Flow's AI cloud servers, waits for it to finish, and intercepts the high-resolution file directly to your disk with exact sequential numbering.",
    "faq.q2": "What does \"Save Missing Files\" do?",
    "faq.a2": "If your batch was paused, interrupted by internet issues, or you created more videos later in the same Flow project, simply click <strong>\"Save Missing Files\"</strong>. The extension scans your project canvas, checks which files you have already downloaded, and saves ONLY the missing ones. No duplicate downloads!",
    "faq.q3": "How does sequential numbering work (001.mp4, 002.mp4)?",
    "faq.a3": "Selecting <strong>\"Oldest first\"</strong> gives number <code>001</code> to the first video generated in your project, <code>002</code> to the second, and so on. You can customize the starting number, the digit padding (<code>01</code>, <code>001</code>, <code>0001</code>), and add custom filename prefixes like <code>SceneA_</code>.",
    "faq.q4": "Can I download both videos and images?",
    "faq.a4": "Yes! In the Download Settings dropdown \"Save Types\", you can choose <strong>\"Both Videos & Pictures\"</strong>, <strong>\"Videos Only\"</strong>, or <strong>\"Pictures Only\"</strong>.",
    "faq.q5": "Do I need to keep the Google Flow tab open?",
    "faq.a5": "Yes. Keep the Flow tab open in Chrome so that Chrome doesn't throttle background javascript execution. You can minimize the window or work in another app. The extension also includes an automatic power lock to prevent your computer from going to sleep while downloading.",
    "faq.q6": "Is Flow Media Downloader free to use?",
    "faq.a6": "Yes, completely free forever. No hidden fees, no subscriptions, no tokens, and no daily limits. Made by Muhammad Asad for the community.",
    "faq.q7": "Is my media data private and safe?",
    "faq.a7": "Completely private. All media files are downloaded directly from Google Flow straight onto your local computer. None of your videos, images, or project files are ever uploaded, analyzed, or sent to any third party.",
    "faq.q8": "How do I contact developer Muhammad Asad for support?",
    "faq.a8": "You can chat directly via WhatsApp: <strong>+92 311 6730583</strong> or email <strong>autoflow.asad@gmail.com</strong>. Quick replies are guaranteed!",
