    "afm.title": "AutoFlow: Veo AI Prompt Suite",
    "afm.subtag": "Batch Generation & Workflow Powerhouse for Google Flow",
    "afm.bannerDesc": "While Flow Downloader extracts and saves your media, AutoFlow creates, matrices, and submits prompts on Google Flow!",
    "afm.b1Title": "Bulk Queue Automation",
    "afm.b1Desc": "Queue prompts in bulk with one click. AutoFlow feeds them automatically into Google Flow without manual typing or repetitive clicks.",
    "afm.b2Title": "Prompt Matrix & Variations",
    "afm.b2Desc": "Combine camera angles, lighting, cinematic styles, and character actions into hundreds of scene variations instantly.",
    "afm.b3Title": "Auto Reference Image Binding",
    "afm.b3Desc": "Automatically attach reference images to each prompt for visual consistency across character scenes.",
    "afm.b4Title": "Save 5+ Hours of Daily Work",
    "afm.b4Desc": "Hands-free background generation. Smart pacing and interval delays prevent Google Flow rate limits while you sleep or work.",
    "afm.b5Title": "The Ultimate Complete Duo",
    "afm.b5Desc": "AutoFlow generates your videos on Flow canvas → Flow Downloader downloads them in sequential 4K order. A complete automated AI studio!",
    "afm.afRole": "The Creator & Queuer",
    "afm.afDetail": "Generates prompts, matrices, reference images, and runs batch submissions.",
    "afm.fdRole": "The Media Downloader",
    "afm.fdDetail": "Extracts 4K/HD files, applies sequential 001.mp4 numbering, and recovers missing clips.",
    "afm.btnChrome": "Install AutoFlow from Chrome Web Store",
    "g.docTitle": "Guía Completa de la A a la Z — Flow Media Downloader",
    "nav.privacy": "🛡️ Política de Privacidad",
