    "g.heroTitle": "Guía de la A a la Z: Flow Media Downloader",
    "g.heroLead": "El manual completo para descargar videos e imágenes de Google Flow (flow.google.com) con numeración secuencial, reescalado a 4K y recuperación de archivos faltantes.",
    "g.tocTitle": "Tabla de Contenidos (A a Z)",
    "g.tocA": "Descripción General y Arquitectura",
    "g.tocB": "Configuración y Fijación en Chrome",
    "g.tocC": "Conexión con Google Flow",
    "g.tocD": "Escaneo de Lienzo",
    "g.tocE": "Gestión de Lista: Eliminar y Borrar Todo",
    "g.tocF": "Calidad: 4K, 1080p y Original",
