    "guide.title": "Comment Utiliser Flow Downloader",
    "guide.desc": "Instructions simples étape par étape pour obtenir des vidéos et images en haute résolution.",
    "guide.badge1": "ÉTAPE 1",
    "guide.badge2": "ÉTAPE 2",
