    "guide.title": "Verwendung von Flow Downloader",
    "guide.desc": "Einfache Schritt-für-Schritt-Anleitung zum Herunterladen hochauflösender Videos und Bilder.",
    "guide.badge1": "SCHRITT 1",
    "guide.badge2": "SCHRITT 2",
    "guide.badge3": "SCHRITT 3",
