    "afm.title": "AutoFlow: Veo AI Prompt Suite",
    "afm.subtag": "Stapelgenerierung und Produktivität für Google Flow",
    "afm.bannerDesc": "Während Flow Downloader Ihre Medien speichert, erstellt und sendet AutoFlow Prompts auf Google Flow!",
    "afm.b1Title": "Stapel-Warteschlange",
    "afm.b1Desc": "Hunderte Prompts mit einem Klick ohne manuelles Tippen einreihen.",
    "afm.b2Title": "Prompt-Matrix & Variationen",
    "afm.b2Desc": "Kombinieren Sie Kamerawinkel, Licht und Stile zu Hunderten Szenen.",
