    "guide.title": "Как Пользоваться Flow Downloader",
    "guide.desc": "Простые пошаговые инструкции для загрузки видео и картинок в высоком разрешении.",
    "guide.badge1": "ШАГ 1",
    "guide.badge2": "ШАГ 2",
    "guide.badge3": "ШАГ 3",
    "guide.badge4": "ШАГ 4",
