    "guide.step1Title": "Открыть Google Flow",
    "guide.step1Text": "Откройте <a href=\"https://flow.google.com\" target=\"_blank\" rel=\"noopener\">flow.google.com</a> в Chrome и откройте свой проект.",
    "guide.step2Title": "Сканировать Холст Проекта",
    "guide.step2Text": "Нажмите <strong>\"Сканировать Проект\"</strong>. Расширение просканирует холст и найдет все видео и картинки.",
    "guide.step3Title": "Редактировать Список и Удалить Клипы",
    "guide.step3Text": "Проверьте найденные медиа. Нажмите значок <strong>🗑️ удалить</strong> рядом с ненужным клипом или <strong>\"Очистить Все\"</strong>.",
    "guide.step4Title": "Выбрать Качество 4K / HD",
    "guide.step4Text": "Выберите <strong>4K Ultra HD</strong> или <strong>1080p HD</strong> для облачного апскейла или <strong>Оригинал (720p)</strong> для мгновенной загрузки.",
    "guide.step5Title": "Последовательная Нумерация",
    "guide.step5Text": "Выберите <strong>\"Сначала старые\"</strong>, чтобы файлы нумеровались по порядку создания (<code>001.mp4</code>, <code>002.mp4</code>).",
    "guide.step6Title": "Скачать Все",
    "guide.step6Text": "Нажмите <strong>\"Скачать Все\"</strong>. Расширение автоматически скачает и сохранит каждый файл.",
    "guide.step7Title": "Сохранить Недостающие (Восстановление)",
    "guide.step7Text": "Сбой сети или создали новые клипы? Нажмите <strong>\"Сохранить Недостающие Файлы\"</strong>! Скачаются только пропущенные клипы.",
    "guide.btnFullGuide": "📖 Открыть Полное Руководство от А до Я (Новая вкладка)",
    "faq.title": "Часто Задаваемые Вопросы (FAQ)",
    "faq.desc": "Популярные вопросы и ответы экспертов о Flow Media Downloader.",
    "faq.q1": "Как работает апскейл в 4K Ultra HD и 1080p?",
    "faq.a1": "Flow показывает превью 720p. При выборе 4K или 1080p расширение запрашивает апскейл на серверах Flow и перехватывает готовый файл.",
    "faq.q2": "Что делает кнопка \"Сохранить Недостающие Файлы\"?",
    "faq.a2": "Она сверяет файлы на вашем компьютере и скачивает ТОЛЬКО те, которых еще нет, без создания дубликатов.",
    "faq.q3": "Как работает последовательная нумерация (001.mp4, 002.mp4)?",
    "faq.a3": "\"Сначала старые\" присваивает 001 первому созданному видео, 002 второму и т.д. Это упрощает монтаж на таймлайне.",
    "faq.q4": "Можно ли скачивать и видео, и картинки?",
    "faq.a4": "Да! В настройках выберите \"Видео и Изображения\", \"Только Видео\" или \"Только Изображения\".",
    "faq.q5": "Нужно ли держать вкладку Google Flow открытой?",
    "faq.a5": "Да, держите вкладку открытой. Расширение включает блокировку сна, предотвращая засыпание компьютера во время скачивания.",
    "faq.q6": "Flow Media Downloader бесплатен?",
    "faq.a6": "Да, полностью бесплатен навсегда. Без подписок, токенов и лимитов. Создан Muhammad Asad.",
    "faq.q7": "Безопасны ли мои данные?",
    "faq.a7": "Полностью приватны. Все файлы сохраняются прямо на ваш диск. Никакие медиа не отправляются на сторонние серверы.",
    "faq.q8": "Как связаться с разработчиком для поддержки?",
    "faq.a8": "Напрямую в WhatsApp: <strong>+92 311 6730583</strong> или по email: <strong>autoflow.asad@gmail.com</strong>.",
