    "guide.step1Title": "Abrir o Google Flow",
    "guide.step1Text": "Abra <a href=\"https://flow.google.com\" target=\"_blank\" rel=\"noopener\">flow.google.com</a> no Chrome e carregue seu projeto.",
    "guide.step2Title": "Escanear Tela do Projeto",
    "guide.step2Text": "Clique em <strong>\"Escanear Projeto\"</strong>. A extensão lista todos os vídeos e imagens gerados.",
    "guide.step3Title": "Organizar Lista & Deletar Clipes",
    "guide.step3Text": "Revise as mídias. Clique no ícone de <strong>🗑️ lixeira</strong> para remover clipes indesejados ou clique em <strong>\"Limpar Tudo\"</strong>.",
    "guide.step4Title": "Escolher Qualidade 4K / HD",
    "guide.step4Text": "Selecione <strong>4K Ultra HD</strong> ou <strong>1080p HD</strong> para ativar o upscale por IA do Flow ou <strong>Original (720p)</strong> para download direto.",
    "guide.step5Title": "Numeração Sequencial",
    "guide.step5Text": "Escolha <strong>\"Mais antigos primeiro\"</strong> para manter a ordem da história (<code>001.mp4</code>, <code>002.mp4</code>).",
    "guide.step6Title": "Baixar Tudo",
    "guide.step6Text": "Clique em <strong>\"Baixar Tudo\"</strong>. A extensão processa a fila e salva cada arquivo automaticamente.",
    "guide.step7Title": "Salvar Arquivos Ausentes (Recuperação)",
    "guide.step7Text": "Queda de internet ou novos clipes gerados? Clique em <strong>\"Salvar Arquivos Ausentes\"</strong>! Apenas os clipes faltantes serão baixados.",
    "guide.btnFullGuide": "📖 Abrir Guia Completo de A a Z (Nova Guia)",
    "faq.title": "Perguntas Frequentes (FAQ)",
    "faq.desc": "Dúvidas comuns e respostas de especialistas sobre o Flow Media Downloader.",
    "faq.q1": "Como funciona o Upscale 4K Ultra HD e 1080p?",
    "faq.a1": "O Flow mostra prévias em 720p. Quando você escolhe 4K ou 1080p, a extensão solicita o arquivo em alta resolução na nuvem do Flow e baixa diretamente.",
    "faq.q2": "O que faz o botão \"Salvar Arquivos Ausentes\"?",
    "faq.a2": "Verifica quais arquivos já foram salvos no seu computador e baixa SOMENTE os faltantes, sem duplicatas.",
    "faq.q3": "Como funciona a numeração sequencial (001.mp4, 002.mp4)?",
    "faq.a3": "\"Mais antigos primeiro\" atribui 001 ao primeiro vídeo gerado, 002 ao segundo, etc., facilitando a edição no Premiere ou DaVinci.",
    "faq.q4": "Posso baixar vídeos e imagens?",
    "faq.a4": "Sim! Nas configurações, escolha \"Vídeos e Imagens\", \"Apenas Vídeos\" ou \"Apenas Imagens\".",
    "faq.q5": "Preciso manter a guia do Google Flow aberta?",
    "faq.a5": "Sim, mantenha a guia aberta no Chrome. A extensão possui bloqueio automático para evitar que o computador durma durante os downloads.",
    "faq.q6": "O Flow Media Downloader é gratuito?",
    "faq.a6": "Sim, 100% gratuito para sempre. Sem taxas, assinaturas ou limites diários. Feito por Muhammad Asad.",
    "faq.q7": "Meus dados de mídia estão seguros?",
    "faq.a7": "Totalmente privados. Todos os arquivos são baixados diretamente no seu computador, sem passar por servidores de terceiros.",
    "faq.q8": "Como falo com o desenvolvedor Muhammad Asad?",
    "faq.a8": "Diretamente pelo WhatsApp: <strong>+92 311 6730583</strong> ou pelo e-mail: <strong>autoflow.asad@gmail.com</strong>.",
