    "g.secATitle": "Visão Geral e Arquitetura Autônoma",
    "g.secAP1": "O <strong>Flow Media Downloader</strong> é uma extensão ultraleve desenvolvida puramente para o <strong>Google Flow</strong> (<code>flow.google.com</code>). Foco total em velocidade e confiabilidade.",
