    "g.secAF4Title": "🔒 Local e Privado",
    "g.secAF4Desc": "Seus arquivos vão direto para o seu disco rígido.",
    "g.secBSub": "PARTE B",
    "g.secBTitle": "Instalação e Fixação no Chrome",
    "g.secBStep1": "Clique no ícone de quebra-cabeça na barra do Chrome.",
    "g.secBStep2": "Encontre o <strong>Flow Media Downloader</strong> e clique no <strong>alfinete</strong>.",
    "g.secBStep3": "Clique no ícone fixado para abrir o painel lateral quando quiser.",
    "g.secBCallout": "<strong>Ativação Gratuita:</strong> Você pode informar seu e-mail ou clicar em <strong>\"Pular\"</strong>. Os downloads nunca são bloqueados!",
    "g.secCSub": "PARTE C",
    "g.secCTitle": "Conectando ao Google Flow",
    "g.secCP1": "Acesse <a href=\"https://flow.google.com\" target=\"_blank\" rel=\"noopener\">flow.google.com</a> no Chrome e abra seu projeto.",
    "g.secCP2": "Observe o indicador de status no topo do painel:",
    "g.secCStatus1": "<span style=\"color:#10b981; font-weight:700;\">🟢 Conectado ao Flow</span> — Pronto para escanear e baixar!",
    "g.secCStatus2": "<span style=\"color:#f59e0b; font-weight:700;\">🟡 Sem Flow</span> — Abra o Flow em uma guia ativa.",
    "g.secDSub": "PARTE D",
    "g.secDTitle": "Escaneamento da Tela e Scroller",
    "g.secDP1": "O Flow usa visualização virtualizada: blocos fora da tela são descarregados da memória.",
    "g.secDP2": "Ao clicar em <strong>\"Escanear Projeto\"</strong>, a extensão:",
    "g.secDStep1": "Detecta o container de rolagem do Flow.",
    "g.secDStep2": "Percorre a tela suavemente para carregar todas as mídias.",
    "g.secDStep3": "Registra cada vídeo e foto com ID e data.",
    "g.secDStep4": "Retorna ao topo sem atrapalhar sua visualização.",
    "g.secDP3": "Os contadores são atualizados na hora.",
    "g.secESub": "PARTE E",
    "g.secETitle": "Organizar Lista — Excluir e Limpar",
    "g.secEP1": "A lista de itens encontrados é exibida no painel:",
    "g.secEF1": "<strong>Excluir Item (🗑️):</strong> Remove o clipe indesejado da fila de download.",
    "g.secEF2": "<strong>Limpar Tudo (🗑️ Limpar Tudo):</strong> Reseta a lista inteira.",
    "g.secEF3": "<strong>Renumeração Automática:</strong> A sequência é mantida sem buracos.",
    "g.secEF4": "<strong>Contador Dinâmico:</strong> O botão mostra o número exato de arquivos.",
    "g.secECallout": "<strong>Economize Espaço:</strong> Não baixe tomadas descartadas.",
    "g.secFSub": "PARTE F",
    "g.secFTitle": "Qualidade: 4K Ultra HD, 1080p e Original",
    "g.secFP1": "Suporte a todos os níveis de qualidade do Google Flow:",
    "g.secFQ1": "<strong>4K Ultra HD:</strong> Solicita a renderização em 4K na nuvem e intercepta o arquivo pronto.",
    "g.secFQ2": "<strong>1080p HD:</strong> O upscale padrão em alta definição do Flow.",
    "g.secFQ3": "<strong>Original (720p):</strong> Download direto e instantâneo sem espera.",
    "g.secFQ4": "<strong>GIF 270p:</strong> Pré-visualizações animadas leves.",
    "g.secFCallout": "<strong>Proteção Fallback:</strong> Se o upscale demorar mais de 3 minutos, a versão original é baixada automaticamente.",
    "g.secGSub": "PARTE G",
    "g.secGTitle": "Numeração Sequencial",
    "g.secGP1": "Organização pronta para Premiere Pro, DaVinci Resolve ou CapCut:",
    "g.secGN1": "<strong>Mais antigos primeiro:</strong> Primeiro vídeo criado = <code>001.mp4</code>.",
    "g.secGN2": "<strong>Como exibido:</strong> Do mais recente ao mais antigo.",
    "g.secGN3": "<strong>Dígitos:</strong> Escolha <code>01</code>, <code>001</code> ou <code>0001</code>.",
    "g.secGN4": "<strong>Prefixo:</strong> Ex: <code>Cena1_001.mp4</code>.",
    "g.secGN5": "<strong>Pasta de Destino:</strong> Subpasta em Downloads.",
    "g.secHSub": "PARTE H",
    "g.secHTitle": "A Super-Função \"Salvar Arquivos Ausentes\"",
    "g.secHP1": "Internet caiu ou gerou mais 15 cenas? Não precisa baixar tudo de novo!",
    "g.secHP2": "Basta clicar em <strong>\"Salvar Arquivos Ausentes\"</strong>:",
    "g.secHStep1": "A extensão reescaneia a tela do Flow.",
    "g.secHStep2": "Verifica quais números já estão no seu computador.",
    "g.secHStep3": "Cria uma fila APENAS com os arquivos que faltam.",
    "g.secHStep4": "Baixa com a numeração sequencial correta.",
    "g.secHCallout": "<strong>Sem Duplicatas:</strong> Economize tempo e espaço em disco.",
    "g.secISub": "PARTE I",
    "g.secITitle": "Controle de Fila e Modo de Espera",
    "g.secIP1": "Controles em tempo real durante os downloads:",
    "g.secICtrl1": "<strong>Pausar:</strong> Pausa após o arquivo atual.",
    "g.secICtrl2": "<strong>Retomar:</strong> Continua de onde parou.",
    "g.secICtrl3": "<strong>Parar:</strong> Encerra a fila com segurança.",
    "g.secICtrl4": "<strong>Repetir Falhas:</strong> Tenta novamente itens com erro de rede.",
    "g.secICallout": "<strong>Mantenha a guia aberta:</strong> A trava automática de energia impede o PC de suspender a atividade.",
    "g.secJSub": "PARTE J",
