    "g.secLDuo": "<strong style=\"color: #c084fc;\">O Melhor Duo para Criadores de IA:</strong><p style=\"margin: 4px 0 0; color: #e2e8f0;\"><strong>1. AutoFlow</strong> gera suas cenas no Flow.<br><strong>2. Flow Downloader</strong> numera (<code>001.mp4</code>) e baixa tudo em 4K.<br>Juntos formam um estúdio de produção completo!</p>",
