    "afm.title": "AutoFlow: Veo AI 提示词套件",
    "afm.subtag": "Google Flow 批量生成与工作流加速利器",
    "afm.bannerDesc": "Flow Downloader 负责提取高清媒体，AutoFlow 负责在 Google Flow 上批量生成与排队提示词！",
    "afm.b1Title": "批量队列全自动",
    "afm.b1Desc": "一键排队数百条提示词，无需手动重复复制粘贴与点击。",
