    "guide.step4Title": "4K / HD 画質を選択",
    "guide.step4Text": "Flow の高画質化エンジンを利用するには <strong>4K Ultra HD</strong> または <strong>1080p HD</strong> を、即時保存なら <strong>オリジナル (720p)</strong> を選択します。",
    "guide.step5Title": "連番ナンバリング",
    "guide.step5Text": "ストーリーのタイムライン順に並べるには<strong>「古い順」</strong>（<code>001.mp4</code>, <code>002.mp4</code>）を選択します。",
    "guide.step6Title": "すべてダウンロード",
    "guide.step6Text": "<strong>「すべてダウンロード」</strong>を押すと、順番に自動保存されます。",
    "guide.step7Title": "不足ファイルを保存（差分ダウンロード）",
    "guide.step7Text": "回線が切れたり後からクリップを追加した場合は、<strong>「不足ファイルを保存」</strong>を押すだけで未保存分だけを正確に取得します。",
    "guide.btnFullGuide": "📖 完全版 A to Z ガイドを開く（新しいタブ）",
    "faq.title": "よくある質問 (FAQ)",
    "faq.desc": "Flow Media Downloader に関する疑問と回答。",
    "faq.q1": "4K Ultra HD および 1080p アップスケールはどのように機能しますか？",
    "faq.a1": "Flow のキャンバスは通常 720p です。4K や 1080p を選ぶと、拡張機能が Flow のクラウドレンダリングをトリガーし高画質ファイルを保存します。",
    "faq.q2": "「不足ファイルを保存」は何をしますか？",
    "faq.a2": "すでにローカルに保存されている番号をチェックし、まだダウンロードされていない差分だけを取得します。二重ダウンロードは発生しません。",
    "faq.q3": "連番ナンバリング（001.mp4, 002.mp4）の利点は何ですか？",
    "faq.a3": "古い順にすることで、Premiere Pro や DaVinci Resolve のタイムラインに並べた際にそのままシーン順で並びます。",
    "faq.q4": "動画と画像の両方をダウンロードできますか？",
    "faq.a4": "はい！設定の保存タイプで「動画と画像の両方」「動画のみ」「画像のみ」を選択できます。",
    "faq.q5": "Google Flow のタブを開いたままにする必要がありますか？",
    "faq.a5": "はい。ブラウザのタブは開いたままにしてください。ダウンロード中のスリープを防ぐ機能も搭載しています。",
    "faq.q6": "Flow Media Downloader は無料ですか？",
    "faq.a6": "はい、永久に完全無料です。サブスクリプションやトークン、制限はありません。Muhammad Asad により制作されました。",
    "faq.q7": "メディアデータは安全でプライベートですか？",
    "faq.a7": "完全にプライベートです。ファイルは直接ローカル PC にダウンロードされ、外部サーバーへ送信されることはありません。",
    "faq.q8": "開発者への問い合わせ方法は？",
    "faq.a8": "WhatsApp（<strong>+92 311 6730583</strong>）またはメール（<strong>autoflow.asad@gmail.com</strong>）でお気軽にご連絡ください。",
    "footer.guide": "📖 ガイド",
