    "guide.step1Title": "Google Flow Öffnen",
    "guide.step1Text": "Öffnen Sie <a href=\"https://flow.google.com\" target=\"_blank\" rel=\"noopener\">flow.google.com</a> in Chrome und laden Sie Ihr Projekt.",
    "guide.step2Title": "Projekt-Leinwand Scannen",
    "guide.step2Text": "Klicken Sie auf <strong>\"Projekt Scannen\"</strong>. Die Erweiterung scannt die Leinwand und listet alle Videos und Bilder auf.",
    "guide.step3Title": "Liste Prüfen & Clips Entfernen",
    "guide.step3Text": "Überprüfen Sie die Medien. Klicken Sie auf <strong>🗑️ Löschen</strong> neben unerwünschten Clips oder auf <strong>\"Alle Löschen\"</strong>.",
    "guide.step4Title": "4K / HD Qualität Wählen",
    "guide.step4Text": "Wählen Sie <strong>4K Ultra HD</strong> oder <strong>1080p HD</strong> für das KI-Upscaling von Flow oder <strong>Original (720p)</strong> für sofortigen Download.",
    "guide.step5Title": "Fortlaufende Nummerierung",
    "guide.step5Text": "Wählen Sie <strong>\"Älteste zuerst\"</strong>, damit die Dateien chronologisch nummeriert werden (<code>001.mp4</code>, <code>002.mp4</code>).",
    "guide.step6Title": "Alle Herunterladen",
    "guide.step6Text": "Klicken Sie auf <strong>\"Alle Herunterladen\"</strong>. Die Erweiterung arbeitet die Liste automatisch ab und speichert alle Dateien.",
    "guide.step7Title": "Fehlende Dateien Speichern (Wiederherstellung)",
    "guide.step7Text": "Internetunterbrechung oder neue Clips erstellt? Klicken Sie auf <strong>\"Fehlende Dateien Speichern\"</strong>! Es werden nur fehlende Clips geladen.",
    "guide.btnFullGuide": "📖 Vollständige A-bis-Z-Anleitung Öffnen (Neuer Tab)",
    "faq.title": "Häufig Gestellte Fragen (FAQ)",
    "faq.desc": "Häufige Fragen und Antworten zum Flow Media Downloader.",
    "faq.q1": "Wie funktioniert das 4K Ultra HD und 1080p Upscaling?",
    "faq.a1": "Flow zeigt 720p-Vorschauen. Bei 4K oder 1080p fordert die Erweiterung das hochauflösende Rendern auf den Flow-Servern an und fängt die Datei ab.",
    "faq.q2": "Was bewirkt \"Fehlende Dateien Speichern\"?",
    "faq.a2": "Sie prüft, welche Dateien bereits auf Ihrem Computer vorhanden sind, und lädt nur die fehlenden herunter – ohne Duplikate.",
    "faq.q3": "Wie funktioniert die fortlaufende Nummerierung?",
    "faq.a3": "\"Älteste zuerst\" vergibt 001 an das erste Video, 002 an das zweite usw., ideal für den Schnitt in Premiere Pro oder DaVinci Resolve.",
    "faq.q4": "Kann ich Videos und Bilder herunterladen?",
    "faq.a4": "Ja! Wählen Sie in den Einstellungen \"Videos und Bilder\", \"Nur Videos\" oder \"Nur Bilder\".",
    "faq.q5": "Muss der Google Flow Tab geöffnet bleiben?",
    "faq.a5": "Ja, lassen Sie den Tab in Chrome offen. Ein automatischer Wachhaltemodus verhindert den Ruhezustand Ihres PCs.",
    "faq.q6": "Ist Flow Media Downloader kostenlos?",
    "faq.a6": "Ja, dauerhaft 100% kostenlos. Keine Abos, keine versteckten Kosten. Entwickelt von Muhammad Asad.",
    "faq.q7": "Sind meine Mediendaten sicher und privat?",
    "faq.a7": "Absolut privat. Alle Dateien werden direkt auf Ihren PC geladen. Keine Medien werden an Drittserver gesendet.",
    "faq.q8": "Wie kontaktiere ich den Entwickler Muhammad Asad?",
    "faq.a8": "Direkt per WhatsApp unter <strong>+92 311 6730583</strong> oder per E-Mail an <strong>autoflow.asad@gmail.com</strong>.",
