    "guide.step7Title": "Salvar Arquivos Ausentes (Recuperação)",
    "guide.step7Text": "Queda de internet ou novos clipes gerados? Clique em <strong>\"Salvar Arquivos Ausentes\"</strong>! Apenas os clipes faltantes serão baixados.",
    "guide.btnFullGuide": "📖 Abrir Guia Completo de A a Z (Nova Guia)",
    "faq.title": "Perguntas Frequentes (FAQ)",
    "faq.desc": "Dúvidas comuns e respostas de especialistas sobre o Flow Media Downloader.",
    "faq.q1": "Como funciona o Upscale 4K Ultra HD e 1080p?",
    "faq.a1": "O Flow mostra prévias em 720p. Quando você escolhe 4K ou 1080p, a extensão solicita o arquivo em alta resolução na nuvem do Flow e baixa diretamente.",
    "faq.q2": "O que faz o botão \"Salvar Arquivos Ausentes\"?",
    "faq.a2": "Verifica quais arquivos já foram salvos no seu computador e baixa SOMENTE os faltantes, sem duplicatas.",
    "faq.q3": "Como funciona a numeração sequencial (001.mp4, 002.mp4)?",
    "faq.a3": "\"Mais antigos primeiro\" atribui 001 ao primeiro vídeo gerado, 002 ao segundo, etc., facilitando a edição no Premiere ou DaVinci.",
    "faq.q4": "Posso baixar vídeos e imagens?",
    "faq.a4": "Sim! Nas configurações, escolha \"Vídeos e Imagens\", \"Apenas Vídeos\" ou \"Apenas Imagens\".",
    "faq.q5": "Preciso manter a guia do Google Flow aberta?",
    "faq.a5": "Sim, mantenha a guia aberta no Chrome. A extensão possui bloqueio automático para evitar que o computador durma durante os downloads.",
