    "guide.step1Title": "Ouvrir Google Flow",
    "guide.step1Text": "Ouvrez <a href=\"https://flow.google.com\" target=\"_blank\" rel=\"noopener\">flow.google.com</a> dans Chrome et ouvrez votre projet contenant des médias.",
    "guide.step2Title": "Scanner le Canevas du Projet",
    "guide.step2Text": "Cliquez sur <strong>\"Scanner le Projet\"</strong>. L'extension scanne votre canevas et répertorie toutes les vidéos et images.",
    "guide.step3Title": "Organiser la Liste & Supprimer des Clips",
    "guide.step3Text": "Passez en revue les médias détectés. Cliquez sur l'icône <strong>🗑️ supprimer</strong> pour retirer un clip ou cliquez sur <strong>\"Tout Effacer\"</strong>.",
    "guide.step4Title": "Choisir la Qualité 4K / HD",
    "guide.step4Text": "Sélectionnez <strong>4K Ultra HD</strong> ou <strong>1080p HD</strong> pour déclencher le moteur d'upscale IA de Flow, ou <strong>Original (720p)</strong> pour un téléchargement immédiat.",
    "guide.step5Title": "Numérotation Séquentielle",
    "guide.step5Text": "Choisissez <strong>\"Plus ancien d'abord\"</strong> pour que les fichiers suivent votre scénario (<code>001.mp4</code>, <code>002.mp4</code>).",
    "guide.step6Title": "Tout Télécharger",
    "guide.step6Text": "Cliquez sur <strong>\"Tout Télécharger\"</strong>. L'extension traite automatiquement la file et sauvegarde chaque fichier.",
    "guide.step7Title": "Sauvegarder les Fichiers Manquants (Récupération)",
    "guide.step7Text": "Coupure réseau ou nouveaux clips générés ? Cliquez sur <strong>\"Sauvegarder les Fichiers Manquants\"</strong> ! Seuls les fichiers manquants sont téléchargés.",
    "guide.btnFullGuide": "📖 Ouvrir le Guide Complet A à Z (Nouvel Onglet)",
    "faq.title": "Foire Aux Questions (FAQ)",
    "faq.desc": "Questions fréquentes et réponses d'experts sur Flow Media Downloader.",
    "faq.q1": "Comment fonctionne l'Upscale 4K Ultra HD et 1080p ?",
    "faq.a1": "Flow affiche des aperçus 720p. Lorsque vous choisissez 4K ou 1080p, l'extension déclenche le rendu haute résolution dans le cloud de Flow et télécharge le fichier résultant.",
    "faq.q2": "Que fait \"Sauvegarder les Fichiers Manquants\" ?",
    "faq.a2": "Elle vérifie quels clips ont déjà été sauvegardés sur votre ordinateur et ne télécharge QUE les vidéos ou images manquantes, évitant tout doublon.",
    "faq.q3": "Comment fonctionne la numérotation séquentielle ?",
    "faq.a3": "\"Plus ancien d'abord\" attribue 001 à la première vidéo générée, 002 à la seconde, etc., facilitant le montage dans Premiere Pro ou DaVinci Resolve.",
    "faq.q4": "Puis-je télécharger les vidéos et les images ?",
    "faq.a4": "Oui ! Dans les paramètres, choisissez \"Vidéos et Images\", \"Vidéos Uniquement\" ou \"Images Uniquement\".",
    "faq.q5": "Dois-je laisser l'onglet Google Flow ouvert ?",
    "faq.a5": "Oui, gardez l'onglet Flow ouvert dans Chrome. L'extension intègre un verrou d'éveil pour empêcher la mise en veille de votre ordinateur pendant le téléchargement.",
    "faq.q6": "Flow Media Downloader est-il gratuit ?",
    "faq.a6": "Oui, 100% gratuit et sans limite. Sans abonnement ni jeton. Développé par Muhammad Asad pour la communauté créative.",
    "faq.q7": "Mes données sont-elles sécurisées et privées ?",
    "faq.a7": "Absolument. Tous les fichiers sont téléchargés directement sur votre disque dur. Aucun fichier n'est envoyé vers des serveurs tiers.",
    "faq.q8": "Comment contacter le développeur Muhammad Asad ?",
    "faq.a8": "Vous pouvez discuter directement via WhatsApp au <strong>+92 311 6730583</strong> ou par e-mail à <strong>autoflow.asad@gmail.com</strong>.",
