    "guide.step3Text": "查看检测列表，点击不需要片段旁的 <strong>🗑️ 删除图标</strong>，或点击<strong>\"清空列表\"</strong>重新扫描。",
    "guide.step4Title": "选择 4K / HD 质量",
    "guide.step4Text": "选择 <strong>4K Ultra HD</strong> 或 <strong>1080p HD</strong> 触发 Flow 的 AI 超分辨率引擎，或选择 <strong>原画质 (720p)</strong> 立即下载。",
    "guide.step5Title": "连续编号设置",
    "guide.step5Text": "选择<strong>\"最早生成的在前\"</strong>以匹配剧情时间线（<code>001.mp4</code>, <code>002.mp4</code>）。",
    "guide.step6Title": "下载全部",
    "guide.step6Text": "点击<strong>\"下载全部\"</strong>。扩展将自动处理队列并依次保存所有文件到本地。",
    "guide.step7Title": "保存遗漏文件（断点续传/补全）",
    "guide.step7Text": "网络断线或新生成了片段？点击<strong>\"保存遗漏文件\"</strong>！扩展将仅下载硬盘上缺失的文件，绝不重复下载。",
    "guide.btnFullGuide": "📖 打开完整 A 到 Z 指南（新标签页）",
    "faq.title": "常见问题解答 (FAQ)",
    "faq.desc": "关于 Flow Media Downloader 的常见疑问与解答。",
    "faq.q1": "4K Ultra HD 和 1080p 超分辨率是如何工作的？",
    "faq.a1": "Flow 画布默认显示 720p 预览。当您选择 4K 或 1080p 时，扩展会触发 Flow 云端超分渲染并拦截高清原文件下载。",
    "faq.q2": "\"保存遗漏文件\"有什么用？",
    "faq.a2": "它会自动比对您本地已下载的编号，仅下载缺失或后来新生成的片段，避免重复下载浪费时间和带宽。",
    "faq.q3": "连续编号是如何编排的（001.mp4, 002.mp4）？",
    "faq.a3": "\"最早生成的在前\"会将最早生成的视频命名为 001，第二个命名为 002，导入剪映或 Premiere 时直接按顺序排布。",
    "faq.q4": "可以同时下载视频和图片吗？",
    "faq.a4": "可以！在保存类型下拉菜单中选择\"视频和图片\"、\"仅视频\"或\"仅图片\"。",
    "faq.q5": "需要一直保持 Google Flow 标签页打开吗？",
    "faq.a5": "是的，请在 Chrome 中保持 Flow 标签页打开。扩展内置防睡眠锁，防止电脑在批量下载时进入休眠。",
    "faq.q6": "Flow Media Downloader 真的免费吗？",
    "faq.a6": "是的，永久 100% 免费。无订阅费、无点数限制、无每日上限。由开发者 Muhammad Asad 为创作者社区打造。",
    "faq.q7": "我的媒体数据安全隐私吗？",
    "faq.a7": "绝对隐私。所有文件直接从 Google Flow 保存到您的本地硬盘，任何视频和图片都不会上传到第三方服务器。",
    "faq.q8": "如何联系开发者 Muhammad Asad 获得支持？",
    "faq.a8": "可通过 WhatsApp <strong>+92 311 6730583</strong> 或邮箱 <strong>autoflow.asad@gmail.com</strong> 直接咨询。",
