    "g.secASub": "第 A 部分",
    "g.secATitle": "概览与独立架构",
    "g.secAP1": "<strong>Flow Media Downloader</strong> 是一款专为 <strong>Google Flow</strong> (<code>flow.google.com</code>) 打造的轻量级 Chrome 扩展，专注于将画布上生成的视频与图片高速、稳定地提取到本地硬盘。",
    "g.secAF1Title": "⚡ 极速轻量",
