    "g.secAF4Title": "🔒 本地安全",
    "g.secAF4Desc": "所有文件直接保存到本地下载文件夹，绝不经过第三方服务器。",
    "g.secBSub": "第 B 部分",
    "g.secBTitle": "Chrome 安装与固定",
    "g.secBStep1": "点击 Chrome 浏览器右上角的拼图图标。",
    "g.secBStep2": "找到 <strong>Flow Media Downloader</strong> 并点击<strong>图钉图标</strong>将其固定在工具栏。",
