    "g.secBCallout": "<strong>免费激活说明：</strong>首次启动时会看到激活卡片。您可以输入邮箱以接收更新，也可以点击<strong>\"跳过\"</strong>立即使用，所有下载功能永不锁死！",
    "g.secCSub": "第 C 部分",
    "g.secCTitle": "连接 Google Flow 项目",
    "g.secCP1": "在 Chrome 中访问 <a href=\"https://flow.google.com\" target=\"_blank\" rel=\"noopener\">flow.google.com</a> 并打开包含生成媒体的项目。",
    "g.secCP2": "观察侧边栏顶部的连接状态药丸：",
    "g.secCStatus1": "<span style=\"color:#10b981; font-weight:700;\">🟢 已连接到 Flow</span> — 准备就绪，可立即扫描和下载！",
    "g.secCStatus2": "<span style=\"color:#f59e0b; font-weight:700;\">🟡 未连接 Flow</span> — 请在当前活跃标签页中打开 Flow 项目。",
    "g.secDSub": "第 D 部分",
    "g.secDTitle": "画布扫描与虚拟滚动处理",
    "g.secDP1": "Google Flow 采用了现代视口虚拟化技术：仅屏幕上可见的卡片才会保留在 DOM 中，超出视口的卡片会被自动卸载以节省 GPU 内存。",
    "g.secDP2": "当您点击 <strong>\"扫描项目\"</strong> 时，扩展将执行：",
    "g.secDStep1": "精准定位 Flow 的活动画布滚动容器。",
    "g.secDStep2": "平滑遍历整个项目画布，触发所有懒加载资源。",
    "g.secDStep3": "记录每段视频与图片的唯一元素 ID、生成时间戳与元数据。",
    "g.secDStep4": "平稳返回画布顶部，丝毫不影响您的视觉操作。",
    "g.secDP3": "数据面板即刻显示媒体总数、视频数、图片数与已下载数，并生成检测列表。",
    "g.secESub": "第 E 部分",
    "g.secETitle": "列表整理 — 单项删除与清空列表",
    "g.secEP1": "点击扫描后，侧边栏将完整列出当前画布上的所有媒体：",
    "g.secEF1": "<strong>单项删除按钮 (🗑️)：</strong> 点击废片旁的垃圾桶图标，将其从下载队列中移除。",
    "g.secEF2": "<strong>清空列表 (🗑️ 清空列表)：</strong> 点击右上角清空列表重新扫描。",
    "g.secEF3": "<strong>动态连续重排：</strong> 剔除废片后，剩余项目的编号会自动连续紧凑重排。",
    "g.secEF4": "<strong>实时数量反馈：</strong> 下载按钮会实时显示剩余数量（例如 <code>下载全部 (8)</code>）。",
    "g.secECallout": "<strong>精准把控：</strong> 拒绝废片占用宝贵的本地存储空间与下载带宽。",
    "g.secFSub": "第 F 部分",
    "g.secFTitle": "画质选择：4K Ultra HD、1080p 与原画",
    "g.secFP1": "全面支持 Google Flow 提供的所有清晰度档位：",
    "g.secFQ1": "<strong>4K Ultra HD（4K视频 / 4K图片）：</strong> 自动触发 Flow 的三点菜单，请求云端 AI 4K 渲染，并精准拦截下载 4K 成品。",
    "g.secFQ2": "<strong>1080p HD视频 / 2K图片：</strong> Flow 标准高清超分，通常耗时 30-60 秒。",
    "g.secFQ3": "<strong>原画质（极速直链下载 — 720p/1K）：</strong> 无需等待云端渲染排队，立即极速批量保存。",
    "g.secFQ4": "<strong>GIF 270p：</strong> 提取轻量动图用于快速分享。",
    "g.secFCallout": "<strong>超时自动回退兜底：</strong> 若 Flow 云端超分渲染异常超时（超 3 分钟），扩展会自动下载原画质版本，绝不卡死或漏下任何镜头。",
    "g.secGSub": "第 G 部分",
    "g.secGTitle": "连续文件自动编号",
    "g.secGP1": "为影视后期（剪映、Premiere Pro、DaVinci Resolve）自动整理素材：",
    "g.secGN1": "<strong>最早生成的在前（时间线顺序）：</strong> 最先生成的镜头命名为 <code>001.mp4</code>，第二段为 <code>002.mp4</code>。",
    "g.secGN2": "<strong>按展示顺序（最新在前）：</strong> 从最新生成的镜头开始倒序保存。",
    "g.secGN3": "<strong>补零位数：</strong> 可选 <code>01</code>、<code>001</code> 或大型项目适用的 <code>0001</code>。",
    "g.secGN4": "<strong>自定义前缀：</strong> 如 <code>Scene1_</code>，输出 <code>Scene1_001.mp4</code>。",
    "g.secGN5": "<strong>独立子文件夹：</strong> 在下载目录中建立专门的镜头文件夹。",
    "g.secHSub": "第 H 部分",
    "g.secHTitle": "\"保存遗漏文件\" 超级功能",
    "g.secHP1": "批量下载中途网络闪断，或者稍后在同一个 Flow 项目中又新生成了 15 个镜头？您完全不需要重头下载！",
    "g.secHP2": "只需点击 <strong>\"保存遗漏文件（补全）\"</strong>：",
