    "g.secLDuo": "<strong style=\"color: #c084fc;\">终极 AI 影视创作黄金组合：</strong><p style=\"margin: 4px 0 0; color: #e2e8f0;\"><strong>1. AutoFlow</strong> 负责在 Google Flow 上批量生成镜头并自动排队。<br><strong>2. Flow Downloader</strong> 负责自动拦截、4K 超分并按 <code>001.mp4</code> 顺序保存到本地。<br>两者结合，打造全自动 AI 影视工业级工作流！</p>",
