    "g.secHStep2": "بررسی می‌کند چه شماره‌هایی دانلود نشده یا ناقص مانده‌اند.",
    "g.secHStep3": "صف دقیقی فقط شامل فایل‌های جاافتاده تشکیل می‌دهد.",
    "g.secHStep4": "آن‌ها را با همان شماره‌گذاری صحیح دانلود می‌کند.",
    "g.secHCallout": "این قابلیت ساعت‌ها در زمان و حجم اینترنت شما صرفه‌جویی می‌کند.",
    "g.secISub": "بخش I",
    "g.secITitle": "کنترل صف و جلوگیری از به خواب رفتن رایانه",
    "g.secIP1": "در حین دانلود، کنترل‌های زمان واقعی نمایش داده می‌شوند:",
