    "g.secICtrl3": "نوار پیشرفت: درصد تکمیل و تعداد فایل‌های ذخیره شده.",
    "g.secICtrl4": "قفل بیداری خودکار: جلوگیری از خاموش شدن صفحه یا Sleep رفتن سیستم.",
