    "g.secJSub": "بخش J",
    "faq.q7": "آیا اطلاعات رسانه‌ای من خصوصی و امن است؟",
    "faq.a7": "کاملاً خصوصی است. تمام فایل‌های رسانه‌ای مستقیماً از Google Flow به رایانه محلی شما دانلود می‌شوند. هیچ‌یک از ویدیوها، تصاویر یا فایل‌های پروژه شما هرگز بارگذاری، تجزیه و تحلیل یا به هیچ شخص ثالثی ارسال نمی‌شوند.",
    "g.secKSub": "بخش K",
    "g.secKTitle": "نیاز به راهنمایی دارید یا پیشنهادی دارید؟",
    "g.secKLead": "مستقیماً با محمد اسد، توسعه‌دهنده برنامه گفتگو کنید. پشتیبانی سریع و فردی از طریق واتساپ و ایمیل در دسترس است.",
    "g.secKDev": "توسعه‌دهنده: محمد اسد (Muhammad Asad) — مهندس نرم‌افزار هوش مصنوعی و اتوماسیون رسانه.",
    "g.secLSub": "بخش L · افزونه همراه",
    "afm.title": "AutoFlow: مجموعه تولید خودکار پرامپت ویدیویی Veo AI",
    "g.secLDesc": "در حالی که Flow Downloader فایل‌های ساخته شده را دانلود می‌کند، افزونه AutoFlow کل فرآیند تایپ و ارسال پرامپت‌ها را خودکار می‌سازد.",
    "afm.b1Title": "🚀 ارسال دسته‌ای پرامپت‌ها",
    "afm.b1Desc": "صدها پرامپت را در یک صف بگذارید؛ AutoFlow آن‌ها را به صورت خودکار به گوگل فلو ارسال می‌کند.",
    "afm.b2Title": "🎲 ماتریس و تنوع پرامپت",
    "afm.b2Desc": "زوایای دوربین، نورپردازی و سبک‌های سینمایی را با هم ترکیب کرده و صحنه‌های متنوع بسازید.",
    "afm.b3Title": "🖼️ الصاق خودکار تصاویر مرجع",
    "afm.b3Desc": "اتصال خودکار عکس شخصیت‌ها به پرامپت‌ها برای ثبات ظاهری در ویدیوها.",
    "afm.b4Title": "⏱️ صرفه‌جویی بیش از ۵ ساعت در روز",
    "afm.b4Desc": "تولید مداوم در پس‌زمینه بدون نیاز به نشستن پای رایانه.",
    "g.secLDuo": "ترکیب این دو افزونه یک استودیوی کامل تولید محتوای هوش مصنوعی را برای شما فراهم می‌کند.",
    "afm.btnChrome": "نصب AutoFlow از Chrome Web Store",
    "g.footerCopy": "دانلودر رسانه فلو — استخراج اختصاصی رسانه‌ها از Google Flow",
    "g.footerDisclaimer": "این افزونه هیچ وابستگی رسمی به Google LLC ندارد. \"Google Flow\" علامت تجاری Google LLC است.",
    "act.emailPh": "you@example.com (اختیاری)",
    "act.skip": "رد شدن",
    "scan.reviewDesc": "بررسی رسانه‌ها. کلیپ‌های ناخواسته را قبل از دانلود حذف کنید.",
