    "guide.badge5": "مرحله ۵",
    "guide.badge6": "مرحله ۶",
    "guide.badge7": "مرحله ۷",
    "guide.step1Text": "سایت flow.google.com را در یک زبانه کروم باز کنید و پروژه حاوی ویدیوها یا تصاویر خود را باز نمایید.",
    "guide.step2Text": "روی \"اسکن رسانه‌های Flow\" کلیک کنید. افزونه تمام ویدیوها و تصاویر موجود در بوم را ثبت می‌کند.",
    "guide.step3Text": "فهرست شناسایی شده را بررسی کنید. برای حذف موارد ناخواسته روی دکمه سطل زباله 🗑️ کلیک کنید یا با \"پاک کردن همه\" لیست را ریست کنید.",
    "guide.step4Text": "کیفیت 4K Ultra HD یا 1080p را برای فعال‌سازی موتور آپ‌اسکیل داخلی فلو، یا کیفیت اصلی (720p) را برای دانلود فوری انتخاب کنید.",
    "guide.step5Text": "گزینه \"قدیمی‌ترین در ابتدا\" را انتخاب کنید تا شماره فایل‌ها با سیر داستانی شما هماهنگ شود (001.mp4، 002.mp4). پیشوند و پوشه را تنظیم کنید.",
    "guide.step6Text": "روی \"شروع دانلود دسته‌ای\" کلیک کنید. افزونه به صورت خودکار صف را پردازش کرده و فایل‌ها را بدون نیاز به دخالت شما ذخیره می‌کند.",
    "guide.step7Text": "اینترنت قطع شد یا کلیپ جدید ساختید؟ روی \"ذخیره فایل‌های جاافتاده\" بزنید! فقط مواردی که در دیسک شما وجود ندارند دانلود می‌شوند.",
    "faq.q6": "آیا دانلودر رسانه فلو رایگان است؟",
    "faq.a6": "بله، برای همیشه کاملاً رایگان است. بدون اشتراک، بدون هزینه مخفی و بدون محدودیت روزانه. ساخته شده توسط محمد اسد برای جامعه کاربری.",
    "faq.q8": "چگونه برای پشتیبانی با محمد اسد (توسعه‌دهنده) تماس بگیرم؟",
    "faq.a8": "می‌توانید مستقیماً از طریق واتساپ با شماره 923116730583+ یا ایمیل autoflow.asad@gmail.com چت کنید. پاسخ‌گویی سریع تضمین شده است!",
